mapper.select:
SELECT t.name, t.type, t.status, t.create_time, t.source FROM (
    SELECT cast(name as char(64)) as name, cast(TYPE as char(64)) as type, status, create_time, 'old' source FROM system_dict_type

        deleted ='0'

            AND name LIKE #{reqVO.name}


            AND type LIKE #{reqVO.type}


            AND status = #{reqVO.status}


            AND create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}



    UNION ALL

    SELECT cast(dict_name as char(64)) as name, cast(dict_code as char(64)) as type, null status, null create_time, 'new' source FROM SYS_DICT

        DEL_FLAG ='0'

            AND dict_name LIKE #{reqVO.name}


            AND dict_code LIKE #{reqVO.type}


) t
ORDER BY t.name

SELECT t.name, t.type, t.status FROM (
SELECT cast(name as char(64)) name, cast(type as char(64)) type, status FROM system_dict_type

    deleted ='0'

        AND type in #{it}



UNION ALL

SELECT cast(dict_name as char(64)) as name, cast(dict_code as char(64)) as type, null status FROM SYS_DICT

    DEL_FLAG ='0'

        AND dict_code in #{it}


) t
ORDER BY t.name

SELECT t.name, t.type, t.status, t.create_time, t.source FROM (
SELECT cast(name as char(64)) as name, cast(TYPE as char(64)) as type, status, create_time, 'old' source FROM system_dict_type

    deleted ='0'

        AND name LIKE #{dictTypeRespVO.name}


        AND type LIKE #{dictTypeRespVO.type}


        AND status = #{dictTypeRespVO.status}


        AND create_time BETWEEN #{dictTypeRespVO.createTime[0]} AND #{dictTypeRespVO.createTime[1]}



UNION ALL

SELECT cast(dict_name as char(64)) as name, cast(dict_code as char(64)) as type, EDIT_STATE status, null create_time, 'new' source FROM SYS_DICT

    DEL_FLAG ='0'

        AND dict_name LIKE #{dictTypeRespVO.name}


        AND dict_code LIKE #{dictTypeRespVO.type}


) t
ORDER BY t.name
